INSERT INTO `product_reviews` (`id`, `product_id`, `customer_id`, `rating`, `title`, `comment`, `is_approved`) VALUES
  (1, 1, 1, 5, 'Máy cầm rất nhẹ và mát tay', 'Titan tự nhiên đẹp xuất sắc, pin trâu dùng cả ngày dài không lo hết, camera zoom 5x chụp concert rất nét!', 1),
  (2, 4, 3, 5, 'Cỗ máy làm việc hoàn hảo', 'Màn hình 120Hz siêu mượt, chip M3 Pro build code NodeJS và Docker chạy cực kỳ êm và mát, không hề nghe tiếng quạt.', 1),
  (3, 9, 3, 5, 'Chuột công thái học tốt nhất từng dùng', 'Cuộn chuột vô cực MagSpeed quá mượt mà, dùng 8 tiếng mỗi ngày không hề bị mỏi cổ tay.', 1),
  (4, 6, 2, 4, 'Chống ồn ấn tượng nhưng hơi cấn khi nằm', 'Chống ồn siêu tốt trên máy bay và quán cafe ồn ào. Âm bass tròn trịa. Điểm trừ duy nhất là case đựng hơi to so với đời XM4.', 1);

